/* LOESS public crowd-observation overlay for ECHOREPO /explore.
 * The data are a separate external source, not ECHO samples or soil measurements.
 * Expects normalized static/geo/loess_surveys.geojson generated by
 * tools/build_loess_geojson.py. No third-party icons, API keys or credentials.
 */
(function () {
  'use strict';

  const SOURCE_URL = 'https://www.loess-soil-map.eu/map';
  // Public layer is intentionally ACCEPTED-only, even with a QA GeoJSON file.
  const ACCEPTED_STATUS = 'ACCEPTED';
  const CATEGORIES = Object.freeze({
    dry:         { label: 'Dry soil',              color: '#a56c00', icon: 'bi-sun-fill' },
    wet:         { label: 'Wet soil',              color: '#137cc1', icon: 'bi-droplet-fill' },
    erosion:     { label: 'Erosion',               color: '#64748b', icon: 'bi-wind' },
    sealed:      { label: 'Sealed soil',           color: '#a45317', icon: 'bi-bricks' },
    degradation: { label: 'Soil degradation',      color: '#c23838', icon: 'bi-exclamation-triangle-fill' },
    organic:     { label: 'Loss of organic matter',color: '#7952ac', icon: 'bi-flower3' },
    ph:          { label: 'pH',                    color: '#8460ba', icon: 'bi-activity' },
    biodiversity:{ label: 'Biodiversity',          color: '#398453', icon: 'bi-bug-fill' },
    other:       { label: 'Other/uncategorized',   color: '#55606c', icon: 'bi-geo-alt-fill' }
  });

  function escapeText(value) { return value == null ? '' : String(value); }
  function addRow(container, label, value) {
    if (value === null || value === undefined || value === '') return;
    const row = document.createElement('div');
    row.className = 'loess-popup-row';
    const heading = document.createElement('strong');
    heading.textContent = label + ': ';
    const text = document.createElement('span');
    text.textContent = escapeText(value);
    row.append(heading, text);
    container.appendChild(row);
  }

  function popupFor(props, category) {
    const el = document.createElement('div');
    el.className = 'loess-popup';
    const title = document.createElement('div');
    title.className = 'loess-popup-heading';
    title.textContent = 'LOESS · ' + CATEGORIES[category].label;
    title.style.borderColor = CATEGORIES[category].color;
    el.appendChild(title);
    addRow(el, 'Place', props.place_name);
    addRow(el, 'Country', props.country_code);
    addRow(el, 'Observed', props.observed_at);
    addRow(el, 'Affected radius', Number.isFinite(Number(props.radius_m)) && props.radius_m !== null && props.radius_m !== ''
      ? Number(props.radius_m) + ' m' : null);
    addRow(el, 'Description', props.description);
    addRow(el, 'Potential cause', props.potential_cause);
    addRow(el, 'Category (original)', props.category_original);
    addRow(el, 'Review status', props.status);
    addRow(el, 'LOESS observation ID', props.source_id);
    const foot = document.createElement('small');
    foot.className = 'loess-popup-source';
    foot.textContent = 'Citizen-reported soil condition · Source: ';
    const link = document.createElement('a');
    link.href = SOURCE_URL;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = 'LOESS Soil Map';
    foot.appendChild(link);
    el.appendChild(foot);
    return el;
  }

  function injectCss() {
    if (document.getElementById('loess-overlay-styles')) return;
    const sheet = document.createElement('style');
    sheet.id = 'loess-overlay-styles';
    sheet.textContent = `
      .loess-point-icon { background:transparent!important; border:0!important; }
      .loess-point { width:24px;height:24px;box-sizing:border-box;display:grid;
        place-items:center;border-radius:50%;background:var(--loess-color);
        border:2px solid #fff;box-shadow:0 1px 6px #0008;color:#fff;font-size:12px; }
      .loess-point:focus-visible { outline:3px solid #111; }
      .loess-popup { font-size:13px;line-height:1.55;min-width:210px;max-width:320px; }
      .loess-popup-heading { font-weight:700;border-left:5px solid;padding-left:8px;margin:0 0 8px; }
      .loess-popup-row { margin:0 0 7px;overflow-wrap:anywhere;white-space:pre-wrap; }
      .loess-popup-source { display:block;border-top:1px solid #ddd;padding-top:6px;color:#555; }
      .loess-filter {background:#fff;padding:8px 10px;border-radius:8px;
        box-shadow:0 1px 5px #0004;max-height:260px;overflow:auto;
        font-size:12px;max-width:205px;}
      .loess-filter-title { font-weight:700;margin-bottom:6px; }
      .loess-filter label { display:flex;align-items:center;gap:7px;margin-bottom:4px;
        cursor:pointer;line-height:1.2; }
      .loess-filter-swatch { width:10px;height:10px;min-width:10px;border-radius:50%; }
      .loess-filter input { cursor:pointer; }
      .loess-filter-note {font-size:11px;color:#555;margin-top:5px;}
    `;
    document.head.appendChild(sheet);
  }

  function createLayer(map, { url = '/static/geo/loess_surveys.geojson?v=3' } = {}) {
    if (!window.L || !map) return null;
    injectCss();
    const wrapper = L.layerGroup();
    const groups = {};
    const enabled = {};
    for (const name of Object.keys(CATEGORIES)) {
      enabled[name] = true;
      groups[name] = L.layerGroup();
      wrapper.addLayer(groups[name]);
    }
    let loaded = false;
    let promise = null;
    let legend = null;
    let loadedCount = 0;
    let errorMessage = '';

    // Avoid overlays obscuring sample popups; draw the circles behind the icons.
    if (!map.getPane('loessCirclePane')) {
      map.createPane('loessCirclePane');
      map.getPane('loessCirclePane').style.zIndex = 355;
    }
    if (!map.getPane('loessMarkerPane')) {
      map.createPane('loessMarkerPane');
      map.getPane('loessMarkerPane').style.zIndex = 625;
    }

    function addObservation(feature) {
      const coordinates = feature?.geometry?.coordinates;
      if (feature?.geometry?.type !== 'Point' || !Array.isArray(coordinates)) return false;
      const lon = Number(coordinates[0]);
      const lat = Number(coordinates[1]);
      if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) return false;
      const props = feature.properties || {};
      if (String(props.status || '').toUpperCase() !== ACCEPTED_STATUS) return false;
      const key = CATEGORIES[props.category] ? props.category : 'other';
      const style = CATEGORIES[key];
      const location = [lat, lon];
      const html = `<span class="loess-point" style="--loess-color:${style.color}"><i class="bi ${style.icon}" aria-hidden="true"></i></span>`;
      const icon = L.divIcon({ className: 'loess-point-icon', html, iconSize: [24, 24], iconAnchor: [12, 12] });
      const marker = L.marker(location, { icon, pane: 'loessMarkerPane', title: 'LOESS: ' + style.label, keyboard: true });
      const popup = () => popupFor(props, key);
      marker.bindPopup(popup, { maxWidth: 350, autoPan: true });
      const rawRadius = props.radius_m;
      const radius = rawRadius === null || rawRadius === undefined || rawRadius === '' ? NaN : Number(rawRadius);
      if (Number.isFinite(radius) && radius > 0 && radius <= 100000) {
        const circle = L.circle(location, {
          radius, color: style.color, weight: 2, opacity: 0.8,
          fillColor: style.color, fillOpacity: 0.13,
          pane: 'loessCirclePane', bubblingMouseEvents: false
        });
        circle.bindPopup(popup, { maxWidth: 350, autoPan: true });
        groups[key].addLayer(circle);
      }
      groups[key].addLayer(marker);
      return true;
    }

    function makeLegend() {
      if (legend) return;
      legend = L.control({ position: 'bottomleft' });
      legend.onAdd = function () {
        const div = L.DomUtil.create('div', 'leaflet-control loess-filter');
        L.DomEvent.disableClickPropagation(div);
        L.DomEvent.disableScrollPropagation(div);
        const title = document.createElement('div');
        title.className = 'loess-filter-title';
        title.textContent = `LOESS observations (${loadedCount})`;
        div.append(title);
        for (const [key, meta] of Object.entries(CATEGORIES)) {
          const label = document.createElement('label');
          const box = document.createElement('input');
          box.type = 'checkbox';
          box.checked = enabled[key];
          box.addEventListener('change', () => {
            enabled[key] = box.checked;
            if (box.checked) wrapper.addLayer(groups[key]);
            else wrapper.removeLayer(groups[key]);
          });
          const swatch = document.createElement('span');
          swatch.className = 'loess-filter-swatch';
          swatch.style.backgroundColor = meta.color;
          const labelText = document.createElement('span');
          labelText.textContent = meta.label;
          label.append(box, swatch, labelText);
          div.append(label);
        }
        const note = document.createElement('div');
        note.className = 'loess-filter-note';
        note.textContent = errorMessage || 'Circle radius = reported affected area (m), not location uncertainty.';
        div.appendChild(note);
        return div;
      };
      legend.addTo(map);
    }
    function updateLegend() {
      if (legend) { map.removeControl(legend); legend = null; }
      if (map.hasLayer(wrapper)) makeLegend();
    }
    async function ensureLoaded() {
      if (loaded) return;
      if (promise) return promise;
      promise = (async () => {
        const response = await fetch(url, { credentials: 'same-origin', cache: 'no-store' });
        if (!response.ok) throw new Error(`LOESS overlay HTTP ${response.status}: ${url}`);
        const data = await response.json();
        if (data?.type !== 'FeatureCollection' || !Array.isArray(data.features)) {
          throw new Error('LOESS overlay is not a GeoJSON FeatureCollection');
        }
        let count = 0;
        for (const feature of data.features) if (addObservation(feature)) count++;
        console.info('LOESS overlay: accepted observations rendered:', count,
          '; GeoJSON features:', data.features.length,
          '; data generated:', data.metadata?.generated_at || 'unspecified');
        loadedCount = count;
        loaded = true;
        if (count === 0) {
          errorMessage = 'No geolocated LOESS observations in the supplied GeoJSON.';
          console.warn(errorMessage);
        }
        updateLegend();
      })();
      try { await promise; }
      catch (error) {
        errorMessage = `LOESS unavailable: ${error.message}`;
        console.warn('Could not load LOESS layer:', error);
        updateLegend();
      } finally { promise = null; }
    }
    map.on('overlayadd', event => {
      if (event.layer !== wrapper) return;
      makeLegend();
      void ensureLoaded();
    });
    map.on('overlayremove', event => {
      if (event.layer !== wrapper) return;
      if (legend) { map.removeControl(legend); legend = null; }
    });
    return wrapper;
  }
  window.ECHOREPO_LOESS = Object.freeze({ createLayer, categories: CATEGORIES });
})();
